ALTER TABLE public.trainers ADD COLUMN slug text, ADD COLUMN professional_title text, ADD COLUMN experience_years integer DEFAULT 0, ADD COLUMN biography text, ADD COLUMN philosophy text, ADD COLUMN expertise text[] DEFAULT '{}', ADD COLUMN certifications text[] DEFAULT '{}', ADD COLUMN photo_url text, ADD COLUMN is_demo_profile boolean NOT NULL DEFAULT true;
UPDATE public.trainers SET slug = lower(regexp_replace(full_name, '[^a-zA-Z0-9]+', '-', 'g')), professional_title = CASE trainer_id WHEN 1 THEN 'Functional Fitness Coach' WHEN 2 THEN 'Mindful Movement Instructor' WHEN 3 THEN 'Strength & Conditioning Coach' WHEN 4 THEN 'Indoor Cycling Instructor' WHEN 5 THEN 'Boxing & Conditioning Coach' ELSE 'Mobility & Recovery Coach' END, experience_years = CASE trainer_id WHEN 1 THEN 8 WHEN 2 THEN 7 WHEN 3 THEN 10 WHEN 4 THEN 6 WHEN 5 THEN 9 ELSE 8 END, biography = CASE trainer_id WHEN 1 THEN 'Maya combines a background in recreational athletics with energetic functional training. Her demo profile focuses on building endurance, strength and confidence through adaptable group workouts.' WHEN 2 THEN 'Liam brings a movement-focused background to yoga and Pilates. His demo profile emphasizes balance, breath and sustainable progress for people of all fitness levels.' WHEN 3 THEN 'Jordan works with strength training and recreational sport. His demo profile focuses on progressive resistance training and supportive one-to-one coaching.' WHEN 4 THEN 'Ava combines a passion for cycling with music-led group training. Her demo profile focuses on cardiovascular fitness, pacing and an inclusive class atmosphere.' WHEN 5 THEN 'Marcus draws on a background in recreational boxing and conditioning. His demo profile emphasizes safe technique, coordination and confidence.' ELSE 'Sofia focuses on mobility, movement quality and recovery. Her demo profile combines a recreational sports background with a calm, individualized coaching approach.' END, philosophy = CASE trainer_id WHEN 1 THEN 'Train with purpose, adapt every movement, and celebrate consistency.' WHEN 2 THEN 'Move mindfully and build strength without rushing the process.' WHEN 3 THEN 'Master the basics, progress gradually, and make strength sustainable.' WHEN 4 THEN 'Find your own rhythm and make every ride a step forward.' WHEN 5 THEN 'Technique comes first; confidence follows consistent practice.' ELSE 'Move well first, then build the capacity to move more.' END, expertise = string_to_array(specialty, ' & '), certifications = CASE trainer_id WHEN 1 THEN ARRAY['Demo: functional training qualification','Demo: group fitness instruction'] WHEN 2 THEN ARRAY['Demo: yoga teacher training','Demo: Pilates mat instruction'] WHEN 3 THEN ARRAY['Demo: personal training qualification','Demo: strength and conditioning training'] WHEN 4 THEN ARRAY['Demo: indoor cycling instruction','Demo: group exercise training'] WHEN 5 THEN ARRAY['Demo: boxing fitness instruction','Demo: exercise safety training'] ELSE ARRAY['Demo: mobility coaching training','Demo: corrective exercise education'] END;
CREATE UNIQUE INDEX trainers_slug_unique ON public.trainers(slug);
CREATE TABLE public.announcements (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 title text NOT NULL,
 description text NOT NULL,
 details text NOT NULL,
 category text NOT NULL CHECK (category IN ('Gym Updates','Workout Cancellations','Upcoming Events','Special Offers')),
 publication_date timestamptz NOT NULL DEFAULT now(),
 event_date timestamptz,
 image_url text,
 is_important boolean NOT NULL DEFAULT false,
 is_published boolean NOT NULL DEFAULT true,
 is_demo boolean NOT NULL DEFAULT true,
 workout_id bigint REFERENCES public.workouts(workout_id),
 created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.announcements TO authenticated;
GRANT ALL ON public.announcements TO service_role;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members read published announcements" ON public.announcements FOR SELECT TO authenticated USING (is_published AND publication_date <= now());
CREATE INDEX announcements_latest ON public.announcements(publication_date DESC);
COMMENT ON COLUMN public.announcements.workout_id IS 'Informational association only. Creating an announcement never cancels workouts, bookings, or payments.';